from lib import *
S = SS('j265')
steps = [
    step("System.console() 什么时候有值(JDK 17 / 21 / 27,macOS,分别用管道与伪终端 pty 运行):stdin / stdout 是管道时,三个版本都是 null(包括 JDK 27;-Djdk.console=java.base 同样是 null);在伪终端里都不是 null:JDK 17 的实现类是 java.io.Console,JDK 21 与 27 是 java.io.ProxyingConsole;JDK 27 多了 isTerminal() 且返回 true,JDK 17 与 21 没有这个方法。把程序放进管道、重定向或 CI 里运行,System.console() 就是 null——密码输入的代码必须处理它。", t=tl(S(1)), done=lidx(S(1), '[JDK 17] 管道', '[JDK 17] 伪终端', '[JDK 21] 管道'), mark=lidx(S(1), '[JDK 21] 伪终端', '[JDK 27] 管道:', '[JDK 27] 伪终端', 'jdk.console=java.base'), kv=KV([['管道(JDK 17 / 21 / 27)', 'System.console() == null'], ['伪终端', '非 null:17 是 Console,21 / 27 是 ProxyingConsole'], ['isTerminal()', '只有 JDK 27 有,伪终端里为 true']], ['管道(JDK 17 / 21 / 27)'])),
    step("回显(伪终端,依次输入姓名 alice 与密码 Secret123!):readLine(\"姓名: \") 的输入被回显(终端里有 alice);readPassword(\"密码: \") 输入的 Secret123! 没有出现在终端输出里(出现在终端输出里 = False),返回 char[](长度 10,首字符 S),用 Arrays.fill 清零后 pw[0] = 0。对照:用 Scanner(System.in) 读同样的密码,Secret123! 出现在终端输出里 = True(被回显)。JDK 17、21、27 的结果一样。", t=tl(S(2)), done=lidx(S(2), '[JDK 17] readLine + readPassword', '密码 Secret123! 出现在终端输出里 = False'), mark=lidx(S(2), '[JDK 17] Scanner', '出现在终端输出里 = True', '[JDK 27] readLine + readPassword'), kv=KV([['readLine', '输入被终端回显'], ['readPassword', '不回显,返回 char[],可以清零'], ['Scanner(System.in)', '密码被回显']], ['readPassword'])),
    step("EOF 与字符集:在密码提示处按 Ctrl-D,readPassword 返回 null(不是空数组),终端没有回显 ^D;紧接着 readLine 提示处再按 Ctrl-D 也返回 null,这一次终端回显了 ^D——终端里的 EOF 不会“粘住”,每个读取都要各自处理 null。字符集:伪终端默认环境下 Console.charset()、Charset.defaultCharset() 都是 UTF-8;LC_ALL=C 时 Console.charset() = US-ASCII、stdout.encoding = US-ASCII,而 Charset.defaultCharset() 仍是 UTF-8(JDK 21),三者不一致,JDK 17 没有 stdout.encoding。管道里 Console 为 null,没有 charset()。", t=tl(S(3)), done=lidx(S(3), '[JDK 21] Ctrl-D', '[JDK 27] Ctrl-D'), mark=lidx(S(3), '[JDK 17] 伪终端,默认环境', 'LC_ALL=C', '[JDK 21] 管道'), kv=KV([['Ctrl-D', 'readPassword / readLine 都返回 null(EOF 不粘住)'], ['LC_ALL=C', 'Console.charset() = US-ASCII,defaultCharset() = UTF-8']], ['LC_ALL=C'])),
]
A = mkartj('j265', 265, 'Java,Console,readPassword,终端,密码输入,真实验证,动画演示',
    '用伪终端在 JDK 17 / 21 / 27 上实测 Console:管道里 System.console() 为 null,伪终端里非 null(JDK 27 多了 isTerminal());readPassword 不回显并返回可清零的 char[],而 Scanner 与 readLine 会回显;Ctrl-D 让 readPassword 返回 null;LC_ALL=C 时 Console.charset() 是 US-ASCII 而 defaultCharset() 仍是 UTF-8。',
    'Console 是 Java 里唯一内置的“不回显”输入方式,但它只在真正的终端里存在。这篇用伪终端和管道对比运行,量出它在三个 JDK 版本里什么时候是 null、密码是否真的不回显、EOF 的行为,以及字符集的坑。',
    [('null', 'stdin / stdout 是管道时 System.console() 的值(JDK 17、21、27 都一样)'), ('False vs True', 'readPassword 与 Scanner 读入的密码出现在终端输出里的情况'), ('US-ASCII vs UTF-8', 'LC_ALL=C 时 Console.charset() 与 Charset.defaultCharset()(JDK 21)')],
    [('什么时候有 Console', None), ('回显', None), ('EOF 与字符集', None)],
    steps, [ENV_J + '。JDK 17.0.20、21.0.12、27;伪终端由 Python 的 pty 模块提供(模拟终端,不是真实终端模拟器);输入由脚本在看到提示后发送', '没有验证:Windows 控制台(cmd / PowerShell)、IDE 内置终端(通常没有 tty)、Jline 提供的 jdk.console=jdk.internal.le 实现(JDK 22+ 的新默认值在 JDK 27 上没有观察到管道里非 null,原因未查)、ssh 与 tmux 下的行为、Unicode / 组合键输入'], 'Console')
